package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Setting;
import net.officefloor.hq.app.setting.SettingRepository;

/**
 * A sheet's rates and settings as they stood at the end of a date: every one stored while the sheet's today was on or
 * before it counts (a later one stored for the same grade or key and from-date replacing an earlier), every one stored
 * later does not. The date stands in for the sheet's today.
 */
public final class SheetAsOf {

    private final LocalDate date;
    private final List<Rate> rates;
    private final List<Setting> settings;

    private SheetAsOf(LocalDate date, List<Rate> rates, List<Setting> settings) {
        this.date = date;
        this.rates = rates;
        this.settings = settings;
    }

    public static SheetAsOf read(String sheetId, LocalDate date, RateRepository rates, SettingRepository settings) {
        Map<String, Rate> byKey = new LinkedHashMap<>();
        for (Rate r : rates.storedBy(sheetId, date)) {
            byKey.put(r.grade() + "@" + r.from(), r);
        }
        Map<String, Setting> byFrom = new LinkedHashMap<>();
        for (Setting s : settings.storedBy(sheetId, date)) {
            byFrom.put(s.key() + "@" + s.from(), s);
        }
        return new SheetAsOf(date, new ArrayList<>(byKey.values()), new ArrayList<>(byFrom.values()));
    }

    public LocalDate date() {
        return date;
    }

    /** The grade's rate in force on a date (see RateRepository#find); null when none applies. */
    public Rate rate(String grade, LocalDate on) {
        Rate found = null;
        for (Rate r : rates) {
            if (!Objects.equals(r.grade(), grade) || (r.from() != null && r.from().isAfter(on))) {
                continue;
            }
            if (found == null || (r.from() != null && (found.from() == null || r.from().isAfter(found.from())))) {
                found = r;
            }
        }
        return found == null || (found.to() != null && found.to().isBefore(on)) ? null : found;
    }

    /** The setting's value in force on a date (an undated one applies to every date); null when it has none. */
    public String value(String key, LocalDate on) {
        Setting found = null;
        for (Setting s : settings) {
            if (!s.key().equals(key) || (s.from() != null && s.from().isAfter(on))) {
                continue;
            }
            if (found == null || (s.from() != null && (found.from() == null || s.from().isAfter(found.from())))) {
                found = s;
            }
        }
        return found == null || found.value() == null || found.value().isBlank() ? null : found.value();
    }

    /** The floor in force on a date (a claim's date). */
    public BigDecimal floor(LocalDate on) {
        String value = value(SettingRepository.FLOOR, on);
        return value == null ? SettingRepository.DEFAULT_FLOOR : new BigDecimal(value);
    }

    /** The late percent in force on a date (a 30-day boundary). */
    public BigDecimal latePct(LocalDate on) {
        String value = value(SettingRepository.LATE_PCT, on);
        return value == null ? SettingRepository.DEFAULT_LATE_PCT : new BigDecimal(value);
    }

    /** The cap in force on the date; null when there is none. */
    public BigDecimal cap() {
        String value = value(SettingRepository.CAP, date);
        return value == null ? null : new BigDecimal(value);
    }

    /** The policy date (undated); null when blank (the date applies). */
    public LocalDate policyDate() {
        String value = value(SettingRepository.POLICY_DATE, date);
        return value == null ? null : LocalDate.parse(value);
    }
}
-- A statement can be taken as of a date on or before the sheet's today. taken_on is then that date (the statement
-- date), as_of is it too (null: taken on the sheet's today), and made_on is the sheet's today when it was taken.
ALTER TABLE statement ADD COLUMN as_of DATE;
ALTER TABLE statement ADD COLUMN made_on DATE;
UPDATE statement SET made_on = taken_on;

-- To read the sheet back as it stood at the end of a date, each change keeps the sheet's today when it was made
-- (made_on). Rows stored before this keep 0001-01-01: made before every date.

-- The sheet's today when the person was added (null: added before this was kept; there from the beginning).
ALTER TABLE person ADD COLUMN added_on DATE;

ALTER TABLE person_hold ADD COLUMN made_on DATE DEFAULT DATE '0001-01-01' NOT NULL;

-- Every retirement date given a person, in the order given (the last one made on or before a date is in force then).
CREATE TABLE person_retire_log (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200) NOT NULL,
    person_id  BIGINT       NOT NULL REFERENCES person (id),
    from_date  DATE         NOT NULL,
    made_on    DATE         NOT NULL
);
CREATE INDEX person_retire_log_sheet ON person_retire_log (sheet_id, person_id, id);
INSERT INTO person_retire_log (sheet_id, person_id, from_date, made_on)
    SELECT sheet_id, id, retired_from, DATE '0001-01-01' FROM person WHERE retired_from IS NOT NULL;

-- Every list of dated grades stored for a person, in the order stored: grades is "grade@from" (from blank for none)
-- joined by ";".
CREATE TABLE person_grade_log (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200)  NOT NULL,
    person_id  BIGINT        NOT NULL REFERENCES person (id),
    grades     VARCHAR(2000) NOT NULL,
    made_on    DATE          NOT NULL
);
CREATE INDEX person_grade_log_sheet ON person_grade_log (sheet_id, person_id, id);

-- Every rate stored, in the order stored (a later one replaces an earlier one of the same grade and from-date).
CREATE TABLE rate_log (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200)  NOT NULL,
    grade      VARCHAR(1)    NOT NULL,
    rate       DECIMAL(7, 2) NOT NULL,
    from_date  DATE,
    to_date    DATE,
    made_on    DATE          NOT NULL
);
CREATE INDEX rate_log_sheet ON rate_log (sheet_id, id);
INSERT INTO rate_log (sheet_id, grade, rate, from_date, to_date, made_on)
    SELECT sheet_id, grade, rate, from_date, to_date, DATE '0001-01-01' FROM rate;

-- Every setting value stored, in the order stored (a later one replaces an earlier one of the same key and from-date).
CREATE TABLE setting_log (
    id            BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id      VARCHAR(200) NOT NULL,
    setting_key   VARCHAR(50)  NOT NULL,
    setting_value VARCHAR(2000),
    from_date     DATE         NOT NULL,
    made_on       DATE         NOT NULL
);
CREATE INDEX setting_log_sheet ON setting_log (sheet_id, id);
INSERT INTO setting_log (sheet_id, setting_key, setting_value, from_date, made_on)
    SELECT sheet_id, setting_key, setting_value, from_date, DATE '0001-01-01' FROM setting;
