import { useNavigate, useSearch } from '@tanstack/react-router';

/**
 * Read and write ONE search-param key.
 *
 * State that outlives a click lives in the URL, not in a parent component — a filter, a sort, a
 * toggle, which row is selected. The control that owns a key is a self-contained file, and whoever
 * reads the key does so directly. Search params are an open namespace (declared once in
 * routes/__root.tsx), so a new key needs no schema change.
 *
 *     const [status, setStatus] = useSearchParam('status', asString);
 */
export function useSearchParam<T>(
  key: string,
  decode: (raw: unknown) => T,
): [T, (value: T | undefined) => void] {
  const search = useSearch({ strict: false }) as Record<string, unknown>;
  const navigate = useNavigate();

  const set = (value: T | undefined) => {
    void navigate({
      to: '.', // stay on the current route; only the search changes
      // Only the one key changes; every other param is left exactly as it was, so two controls
      // never clobber each other.
      search: (prev: Record<string, unknown>) => {
        const next = { ...prev };
        if (value === undefined || value === '') {
          delete next[key];
        } else {
          next[key] = value;
        }
        return next;
      },
      replace: true,
    });
  };

  return [decode(search[key]), set];
}

export const asString = (raw: unknown): string => (typeof raw === 'string' ? raw : '');
export const asNumber = (raw: unknown): number | undefined => {
  const n = Number(raw);
  return raw === undefined || raw === '' || Number.isNaN(n) ? undefined : n;
};
export const asFlag = (raw: unknown): boolean => raw === 'true' || raw === true;
import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { useSheetId } from './session';

/** Choose the active sheet by typing its id. Loading an id again re-reads it from the store. */
export function SheetPicker() {
  const [sheetId, setSheetId] = useSheetId();
  const queryClient = useQueryClient();
  const [typed, setTyped] = useState('');
  return (
    <form
      data-testid="sheet-picker"
      onSubmit={(e) => {
        e.preventDefault();
        const id = typed.trim();
        if (id === '') return;
        void queryClient.invalidateQueries({ queryKey: ['sheet', id] });
        if (id !== sheetId) setSheetId(id);
      }}
    >
      <label>
        Sheet <input data-testid="sheet-id-input" value={typed} onChange={(e) => setTyped(e.target.value)} />
      </label>
      <button type="submit" data-testid="sheet-load">
        Load
      </button>
    </form>
  );
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson, putJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPage } from '../../slots/defs/sheetPage';
import { useSheet, type Sheet } from '../session/session';

/** The sheet's today: shown, and changeable. Changing it re-reads the whole sheet. Also whether the sheet is
 *  archived, and archiving it (a steward only). Both share the sheet's one error element. */
function SheetToday({ sheetId, user }: { sheetId: string; user: string }) {
  const sheet = useSheet(sheetId);
  const queryClient = useQueryClient();
  const [typed, setTyped] = useState('');
  const submit = useSubmitOnce();
  const stored = (saved: Sheet) => {
    queryClient.setQueryData(['sheet', sheetId], saved);
    void queryClient.invalidateQueries({ queryKey: ['sheet', sheetId] });
  };
  const save = useMutation({
    mutationFn: (today: string) =>
      putJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}/today`, { today, by: user }),
    onSuccess: stored,
    onSettled: submit.end,
  });
  const archive = useMutation({
    mutationFn: () => postJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}/archive`, { by: user }),
    onSuccess: stored,
  });
  return (
    <form
      data-testid="sheet-today-form"
      onSubmit={(e) => {
        e.preventDefault();
        if (!submit.begin()) return;
        archive.reset();
        save.mutate(typed.trim());
      }}
    >
      Today <span data-testid="sheet-today">{sheet.data?.today}</span>{' '}
      <input
        type="date"
        data-testid="sheet-today-input"
        value={typed}
        onChange={(e) => {
          setTyped(e.target.value);
          save.reset();
          archive.reset();
        }}
      />
      <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
        Set today
      </button>{' '}
      Archived <span data-testid="sheet-archived">{sheet.data?.archived ? 'yes' : 'no'}</span>{' '}
      <button
        type="button"
        data-testid="sheet-archive"
        disabled={archive.isPending}
        onClick={() => {
          save.reset();
          archive.reset();
          archive.mutate();
        }}
      >
        Archive
      </button>
      {(save.isError || archive.isError) && (
        <span data-testid="sheet-error">
          {archive.isError ? 'Could not archive the sheet.' : 'Could not change today.'}
        </span>
      )}
    </form>
  );
}

export const contribution = SheetPage.fill({ order: 0, Component: SheetToday });
